/**
 * One-off dev tool: downloads the circuit outlines used by the challenge and writes
 * `src/lib/circuit-tracks.ts`. Run it with `npm run generate:tracks -w @f1/web`.
 * The app never fetches the dataset at runtime; it only imports the generated file.
 */
import { writeFileSync } from 'node:fs';

const DATASET_URL = 'https://raw.githubusercontent.com/bacinger/f1-circuits/master/circuits';
const OUTPUT = new URL('../src/lib/circuit-tracks.ts', import.meta.url);

/** Our API circuit id -> dataset file id. */
const DATASET_IDS = {
  'circuit-01': 'bh-2002', // Bahrain
  'circuit-02': 'mc-1929', // Monaco
  'circuit-03': 'ca-1978', // Canada
  'circuit-04': 'gb-1948', // Silverstone
  'circuit-05': 'be-1925', // Spa
  'circuit-06': 'it-1922', // Monza
  'circuit-07': 'sg-2008', // Marina Bay
};

const VIEWBOX_SIZE = 1000;
const PADDING = 20;

type Point = [number, number];

async function fetchOutline(datasetId: string): Promise<Point[]> {
  const response = await fetch(`${DATASET_URL}/${datasetId}.geojson`);
  if (!response.ok) throw new Error(`${datasetId}: HTTP ${response.status}`);
  const geojson = await response.json();
  return geojson.features[0].geometry.coordinates;
}

/** Projects lon/lat onto a flat plane, scales to fit the viewBox keeping the aspect ratio, and centres it. */
function toPath(lonLat: Point[]): string {
  const meanLat = lonLat.reduce((sum, [, lat]) => sum + lat, 0) / lonLat.length;
  const lonScale = Math.cos((meanLat * Math.PI) / 180);
  const flat = lonLat.map(([lon, lat]): Point => [lon * lonScale, -lat]);

  const xs = flat.map(([x]) => x);
  const ys = flat.map(([, y]) => y);
  const [minX, minY] = [Math.min(...xs), Math.min(...ys)];
  const width = Math.max(...xs) - minX;
  const height = Math.max(...ys) - minY;

  const scale = (VIEWBOX_SIZE - 2 * PADDING) / Math.max(width, height);
  const offsetX = (VIEWBOX_SIZE - width * scale) / 2;
  const offsetY = (VIEWBOX_SIZE - height * scale) / 2;

  const points = flat.map(
    ([x, y]) =>
      `${(offsetX + (x - minX) * scale).toFixed(1)} ${(offsetY + (y - minY) * scale).toFixed(1)}`,
  );
  return `M${points.join('L')}Z`;
}

const entries: string[] = [];
for (const [circuitId, datasetId] of Object.entries(DATASET_IDS)) {
  entries.push(`  '${circuitId}': '${toPath(await fetchOutline(datasetId))}',`);
}

writeFileSync(
  OUTPUT,
  `// Generated by scripts/generate-circuit-tracks.ts. Do not edit by hand.
// Source: https://github.com/bacinger/f1-circuits by Tomislav Bacinger, MIT license.

/** Side of the square viewBox shared by every track. */
export const TRACK_VIEWBOX_SIZE = ${VIEWBOX_SIZE};

/** SVG path \`d\` of each circuit outline, keyed by the API circuit id. */
export const CIRCUIT_TRACKS: Record<string, string> = {
${entries.join('\n')}
};
`,
);
